#[inline]
pub unsafe fn BitStream_toByte(
    mut bstream: *mut BitStream,
) -> *mut c_uchar {
    let bstream_view: &BitStream = unsafe { &*bstream }; // SAFETY: caller provides a valid pointer to BitStream as required by the original unsafe API.
    let size: size_t = bstream_view.length;
    if size == 0 as size_t {
        return ::core::ptr::null_mut::<c_uchar>();
    }

    let out_len = size.wrapping_add(7 as size_t).wrapping_div(8 as size_t);
    let data = malloc(out_len) as *mut c_uchar;
    if data.is_null() {
        return ::core::ptr::null_mut::<c_uchar>();
    }

    let bytes = size.wrapping_div(8 as size_t);
    let oddbits = size & 7 as size_t;
    let mut p = bstream_view.data;
    let mut out = data;

    let mut i = 0 as size_t;
    while i < bytes {
        let v = ((*p.add(0) as c_uchar) << 7)
            | ((*p.add(1) as c_uchar) << 6)
            | ((*p.add(2) as c_uchar) << 5)
            | ((*p.add(3) as c_uchar) << 4)
            | ((*p.add(4) as c_uchar) << 3)
            | ((*p.add(5) as c_uchar) << 2)
            | ((*p.add(6) as c_uchar) << 1)
            | (*p.add(7) as c_uchar);
        unsafe {
            // SAFETY: p points into the bitstream data and there are at least 8 input bits available for each full output byte; out points into the malloc-allocated output buffer with at least `bytes` writable positions.
            *out = v;
            p = p.add(8);
            out = out.add(1);
        }
        i = i.wrapping_add(1);
    }

    if oddbits > 0 as size_t {
        let v = match oddbits {
            1 => unsafe {
                // SAFETY: oddbits == 1 guarantees one remaining input bit at p.
                (*p.add(0) as c_uchar) << 7
            },
            2 => unsafe {
                // SAFETY: oddbits == 2 guarantees two remaining input bits at p..p+2.
                ((*p.add(0) as c_uchar) << 7) | ((*p.add(1) as c_uchar) << 6)
            },
            3 => unsafe {
                // SAFETY: oddbits == 3 guarantees three remaining input bits at p..p+3.
                ((*p.add(0) as c_uchar) << 7)
                    | ((*p.add(1) as c_uchar) << 6)
                    | ((*p.add(2) as c_uchar) << 5)
            },
            4 => unsafe {
                // SAFETY: oddbits == 4 guarantees four remaining input bits at p..p+4.
                ((*p.add(0) as c_uchar) << 7)
                    | ((*p.add(1) as c_uchar) << 6)
                    | ((*p.add(2) as c_uchar) << 5)
                    | ((*p.add(3) as c_uchar) << 4)
            },
            5 => unsafe {
                // SAFETY: oddbits == 5 guarantees five remaining input bits at p..p+5.
                ((*p.add(0) as c_uchar) << 7)
                    | ((*p.add(1) as c_uchar) << 6)
                    | ((*p.add(2) as c_uchar) << 5)
                    | ((*p.add(3) as c_uchar) << 4)
                    | ((*p.add(4) as c_uchar) << 3)
            },
            6 => unsafe {
                // SAFETY: oddbits == 6 guarantees six remaining input bits at p..p+6.
                ((*p.add(0) as c_uchar) << 7)
                    | ((*p.add(1) as c_uchar) << 6)
                    | ((*p.add(2) as c_uchar) << 5)
                    | ((*p.add(3) as c_uchar) << 4)
                    | ((*p.add(4) as c_uchar) << 3)
                    | ((*p.add(5) as c_uchar) << 2)
            },
            7 => unsafe {
                // SAFETY: oddbits == 7 guarantees seven remaining input bits at p..p+7.
                ((*p.add(0) as c_uchar) << 7)
                    | ((*p.add(1) as c_uchar) << 6)
                    | ((*p.add(2) as c_uchar) << 5)
                    | ((*p.add(3) as c_uchar) << 4)
                    | ((*p.add(4) as c_uchar) << 3)
                    | ((*p.add(5) as c_uchar) << 2)
                    | ((*p.add(6) as c_uchar) << 1)
            },
            _ => 0 as c_uchar,
        };
        unsafe {
            // SAFETY: when oddbits > 0, one final output byte remains within the allocated buffer.
            *out = v;
        }
    }

    data
}

